#include "session_capability_store.h"
PAPACC_RESULT papacc_session_capability_store_init(PAPACC_SESSION_CAPABILITY_STORE *s,PAPACC_SESSION_CAPABILITY_BINDING *b,PAPACC_CAPABILITY_KEY *k,PAPACC_SIZE cap,PAPACC_SIZE per){PAPACC_SIZE i;if(s==NULL||(cap>0U&&(b==NULL||k==NULL||per==0U)))return PAPACC_RESULT_INVALID_ARGUMENT;if(s->initialized)return PAPACC_RESULT_INVALID_STATE;for(i=0U;i<cap;++i)b[i]=(PAPACC_SESSION_CAPABILITY_BINDING)PAPACC_SESSION_CAPABILITY_BINDING_INITIALIZER;s->storage=b;s->key_storage=k;s->capacity=cap;s->keys_per_session=per;s->count=0U;s->initialized=PAPACC_TRUE;return PAPACC_RESULT_OK;}
PAPACC_SESSION_CAPABILITY_SNAPSHOT *papacc_session_capability_store_find(PAPACC_SESSION_CAPABILITY_STORE *s,PAPACC_U64 id){PAPACC_SIZE i;if(s==NULL||!s->initialized||id==0U)return NULL;for(i=0U;i<s->capacity;++i)if(s->storage[i].session_instance_id==id)return &s->storage[i].snapshot;return NULL;}
PAPACC_SESSION_CAPABILITY_SNAPSHOT *papacc_session_capability_store_reserve(PAPACC_SESSION_CAPABILITY_STORE *s,PAPACC_U64 id){PAPACC_SIZE i;if(s==NULL||!s->initialized||id==0U||s->count>=s->capacity||papacc_session_capability_store_find(s,id)!=NULL)return NULL;for(i=0U;i<s->capacity;++i)if(s->storage[i].session_instance_id==0U){s->storage[i].session_instance_id=id;++s->count;return &s->storage[i].snapshot;}return NULL;}
PAPACC_RESULT papacc_session_capability_store_publish(PAPACC_SESSION_CAPABILITY_STORE *s,PAPACC_U64 id,const PAPACC_CAPABILITY_EVALUATION_INPUTS *inputs){PAPACC_SIZE i;PAPACC_SESSION_CAPABILITY_SNAPSHOT *p;PAPACC_BOOL reserved=PAPACC_FALSE;PAPACC_RESULT r;if(s==NULL||!s->initialized||inputs==NULL)return PAPACC_RESULT_INVALID_ARGUMENT;p=papacc_session_capability_store_find(s,id);if(p==NULL){p=papacc_session_capability_store_reserve(s,id);if(p==NULL)return PAPACC_RESULT_LIMIT_EXCEEDED;reserved=PAPACC_TRUE;}for(i=0U;i<s->capacity;++i)if(&s->storage[i].snapshot==p){r=papacc_session_capability_snapshot_publish(p,id,s->key_storage+i*s->keys_per_session,s->keys_per_session,inputs);if(r!=PAPACC_RESULT_OK&&reserved==PAPACC_TRUE)(void)papacc_session_capability_store_remove(s,id);return r;}if(reserved==PAPACC_TRUE)(void)papacc_session_capability_store_remove(s,id);return PAPACC_RESULT_INTERNAL_ERROR;}
PAPACC_RESULT papacc_session_capability_store_remove(PAPACC_SESSION_CAPABILITY_STORE *s,PAPACC_U64 id){PAPACC_SESSION_CAPABILITY_SNAPSHOT *p=papacc_session_capability_store_find(s,id);PAPACC_SESSION_CAPABILITY_BINDING *b;if(p==NULL)return PAPACC_RESULT_INVALID_ARGUMENT;b=(PAPACC_SESSION_CAPABILITY_BINDING*)((char*)p-(PAPACC_SIZE)&((PAPACC_SESSION_CAPABILITY_BINDING*)0)->snapshot);papacc_session_capability_snapshot_release(p);*b=(PAPACC_SESSION_CAPABILITY_BINDING)PAPACC_SESSION_CAPABILITY_BINDING_INITIALIZER;--s->count;return PAPACC_RESULT_OK;}
void papacc_session_capability_store_shutdown(PAPACC_SESSION_CAPABILITY_STORE *s){PAPACC_SIZE i;if(s==NULL||!s->initialized)return;for(i=0U;i<s->capacity;++i)if(s->storage[i].session_instance_id!=0U)papacc_session_capability_snapshot_release(&s->storage[i].snapshot);*s=(PAPACC_SESSION_CAPABILITY_STORE)PAPACC_SESSION_CAPABILITY_STORE_INITIALIZER;}
